def nmse(p,f):
    r=f(p)-y
    return np.mean(r**2)/v
base=lambda p,t: p[0]+p[1]/t+p[2]*t+p[3]*np.exp(-t)
forms={
 'hill_const_K': (lambda p: -base(p,t)/(1+(A/p[4])**p[5]), 6),
 'exp_A_pow': (lambda p: -base(p,t)*np.exp(-p[4]*A**p[5]), 6),
 'base+MM': (lambda p: -base(p,t)-p[4]*t*A/(p[5]+A)*0 - (p[4]+p[5]*t)*A/(p[6]+A), 7),
 'base_times_MM': (lambda p: -base(p,t)*(1+p[4]*t)/(1+p[5]*A**p[6]), 7),
 'base_sub_MMt': (lambda p: -(base(p,t)+(p[4]+p[5]*t)*A/(p[6]+A)*0+ 0) * (1+p[4]/(1+p[5]*A)), 6),
 'a_plus_b_expA': (lambda p: -(p[0]+p[1]/t+p[2]*t+p[3]*np.exp(-t))*np.exp(-p[4]*A) - p[5]*A*np.exp(-p[6]*t), 7),
}
rng=np.random.default_rng(0)
for name,(f,k) in forms.items():
    best=(9e9,None)
